class Solution:
    def totalNumbers(self, digits):
        from collections import Counter
        cnt = Counter(digits)
        ans = 0
        for a in range(1, 10):
            for b in range(10):
                for c in (0, 2, 4, 6, 8):
                    need = Counter([a, b, c])
                    if all(cnt[d] >= v for d, v in need.items()):
                        ans += 1
        return ans

