    def totalNumbers(self, digits):
        from itertools import permutations
        seen = set()
        for p in permutations(digits, 3):
            if p[0] != 0 and p[2] % 2 == 0:
                seen.add(p[0] * 100 + p[1] * 10 + p[2])
        return len(seen)

