class Solution {
    public int totalNumbers(int[] digits) {
        Set<Integer> seen = new HashSet<>();
        permute(digits, 0, seen);
        return seen.size();
    }
    private void permute(int[] a, int i, Set<Integer> seen) {
        if (i == 3) {
            if (a[0] != 0 && a[2] % 2 == 0)
                seen.add(a[0]*100 + a[1]*10 + a[2]);
            return;
        }
        Set<Integer> used = new HashSet<>();
        for (int j = i; j < a.length; j++) {
            if (!used.add(a[j])) continue;
            int t = a[i]; a[i] = a[j]; a[j] = t;
            permute(a, i + 1, seen);
            t = a[i]; a[i] = a[j]; a[j] = t;
        }
    }
}

