var totalNumbers = function(digits) {
    const seen = new Set();
    const perm = (arr, i) => {
        if (i === 3) {
            if (arr[0] !== 0 && arr[2] % 2 === 0)
                seen.add(arr[0]*100 + arr[1]*10 + arr[2]);
            return;
        }
        const used = new Set();
        for (let j = i; j < arr.length; j++) {
            if (used.has(arr[j])) continue;
            used.add(arr[j]);
            [arr[i], arr[j]] = [arr[j], arr[i]];
            perm(arr, i + 1);
            [arr[i], arr[j]] = [arr[j], arr[i]];
        }
    };
    perm(digits.slice(), 0);
    return seen.size();
};
